<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { decideServiceAccess, listReceivedServiceAccessGrants, listResources } from "../api";
import type { Resource, ServiceAccessGrant } from "../api/contracts";
import Alert from "../components/Alert.vue";
import DataPanel from "../components/DataPanel.vue";
import ServiceNavigation from "../components/ServiceNavigation.vue";
import { useCatalogsStore } from "../stores/catalogs";
const catalogs=useCatalogsStore(), targetId=ref(""), grants=ref<ServiceAccessGrant[]>([]), resources=ref<Resource[]>([]), busy=ref(false), error=ref(""); const pending=computed(()=>grants.value.filter(grant=>grant.status==='PENDING'));
async function load(){grants.value=[];resources.value=[];if(!targetId.value)return;try{const [received,listed]=await Promise.all([listReceivedServiceAccessGrants(targetId.value),listResources(targetId.value)]);grants.value=received.data;resources.value=listed.data}catch(cause){error.value=cause instanceof Error?cause.message:'No fue posible cargar las solicitudes.'}}
async function decide(grant:ServiceAccessGrant,approve:boolean){busy.value=true;try{await decideServiceAccess(targetId.value,grant.id,approve);await load()}catch(cause){error.value=cause instanceof Error?cause.message:'No fue posible registrar la decisión.'}finally{busy.value=false}}
const label=(id:string|null)=>id&&resources.value.find(resource=>resource.id===id)?`${resources.value.find(resource=>resource.id===id)!.method} ${resources.value.find(resource=>resource.id===id)!.path}`:'Rol técnico agrupado';watch(targetId,load);
</script>
<template><div class="review-page"><Alert v-if="error" type="error" :message="error" @close="error=''"/><ServiceNavigation /><DataPanel title="Solicitudes pendientes" :count="pending.length" empty="" :show-content-when-empty="true" :eyebrow="null"><div class="review-toolbar"><label>Aplicación propietaria<select v-model="targetId"><option value="">Selecciona una aplicación</option><option v-for="app in catalogs.apps" :key="app.id" :value="app.id">{{app.name}}</option></select></label><p>Aprueba únicamente los accesos que esta aplicación deba conceder.</p></div><div v-if="pending.length" class="review-list"><article v-for="grant in pending" :key="grant.id"><div><strong>{{label(grant.resourceId)}}</strong><span>Rol {{grant.technicalRole}} · solicitada {{new Date(grant.requestedAt).toLocaleDateString('es-CO',{dateStyle:'medium'})}}</span></div><div class="actions"><button class="approve" :disabled="busy" @click="decide(grant,true)">Aprobar</button><button class="reject" :disabled="busy" @click="decide(grant,false)">Rechazar</button></div></article></div><div v-else class="review-empty"><strong>{{targetId?'No hay solicitudes pendientes':'Elige una aplicación para revisar su bandeja'}}</strong><span>{{targetId?'Las nuevas solicitudes aparecerán aquí para que puedas decidirlas.':'La bandeja corresponde a la aplicación dueña del recurso.'}}</span></div></DataPanel></div></template>
<style scoped>.review-page{display:grid;gap:20px}.service-nav{display:flex;gap:2px;border-bottom:1px solid var(--line)}.service-nav a{color:var(--text);padding:0 14px 12px;text-decoration:none;font-size:13px}.service-nav .active{color:var(--ink);border-bottom:2px solid var(--green);font-weight:600}.review-toolbar{display:flex;align-items:end;gap:18px;padding:0 26px 18px}.review-toolbar label{display:grid;gap:7px;min-width:300px;color:var(--text);font-size:12px;font-weight:600}.review-toolbar select{height:36px;border:1px solid var(--line);border-radius:6px;padding:0 10px;background:#fff}.review-toolbar p{margin:0;color:var(--text);font-size:12px}.review-list{border-top:1px solid var(--soft-line)}.review-list article{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:16px 26px;border-top:1px solid var(--soft-line)}.review-list article>div:first-child{display:grid;gap:5px}.review-list strong{font-size:13px}.review-list span{color:var(--text);font-size:12px}.actions{display:flex;gap:8px}.actions button{height:34px;border-radius:6px;padding:0 11px;font-size:12px}.approve{border:0;background:var(--ink);color:#fff}.reject{border:1px solid rgba(185,61,60,.35);background:#fff;color:var(--red)}.review-empty{display:grid;gap:6px;padding:32px 26px;color:var(--text);font-size:13px}.review-empty strong{color:var(--ink)}@media(max-width:700px){.service-nav{overflow:auto}.service-nav a{white-space:nowrap}.review-toolbar{align-items:stretch;flex-direction:column}.review-toolbar label{min-width:0}.review-list article{align-items:stretch;flex-direction:column}}</style>
